/* Glint Research's Legally Distinct Clone — original dark teal/cyan theme */
* { box-sizing: border-box; margin: 0; padding: 0; }
:root {
  --bg: #0e1c26;
  --bg2: #142733;
  --panel: #1b3342;
  --panel2: #224050;
  --line: #2e5266;
  --text: #e8f4f8;
  --dim: #93b3c2;
  --accent: #19c2ff;
  --accent2: #19ff8c;
  --gold: #ffd23f;
  --red: #e54b4b;
  --radius: 10px;
}
html, body { height: 100%; }
body {
  background: var(--bg);
  color: var(--text);
  font-family: 'Segoe UI', system-ui, -apple-system, sans-serif;
  overflow-x: hidden;
}
a { color: var(--accent); text-decoration: none; }
button { font-family: inherit; }
.hidden { display: none !important; }

/* ---------- nav ---------- */
#topnav {
  display: flex; align-items: center; gap: 4px;
  background: var(--bg2);
  border-bottom: 2px solid var(--line);
  padding: 0 16px; height: 54px;
  position: sticky; top: 0; z-index: 100;
}
#topnav > a { color: var(--dim); font-weight: 600; padding: 6px 12px; border-radius: 8px; }
#topnav > a:hover { color: var(--text); background: var(--panel); }
#topnav > a.active { color: var(--accent); }
.logo { display: flex; align-items: center; gap: 9px; margin-right: 14px; }
.logo-block {
  width: 26px; height: 26px; border-radius: 7px;
  background: linear-gradient(135deg, var(--accent), #1976d2);
  box-shadow: inset 0 0 0 5px rgba(14,28,38,.55);
}
.logo-text { color: var(--text) !important; font-weight: 800; letter-spacing: 1px; line-height: 1; font-size: 17px; }
.logo-text small { display: block; font-size: 7.5px; letter-spacing: .4px; color: var(--dim); font-weight: 600; }
.create-btn { background: var(--accent2); color: #0a2a18 !important; margin-left: 6px; }
.create-btn:hover { background: #46ffa6 !important; color: #0a2a18 !important; }
.nav-right { margin-left: auto; display: flex; align-items: center; gap: 12px; }
.glimmers { color: var(--gold); font-weight: 700; }
#nav-profile { display: flex; align-items: center; gap: 7px; color: var(--text); font-weight: 600; }
.mini-avatar { width: 30px; height: 30px; border-radius: 8px; background: var(--panel); display: inline-block; overflow: hidden; }
.mini-avatar svg { width: 100%; height: 100%; }
.ghost-btn { background: none; border: 1px solid var(--line); color: var(--dim); border-radius: 8px; padding: 4px 9px; cursor: pointer; }
.ghost-btn:hover { color: var(--text); border-color: var(--dim); }

/* ---------- layout ---------- */
#page { max-width: 1180px; margin: 0 auto; padding: 24px 18px 80px; }
#page.full { max-width: none; padding: 0; }
h1 { font-size: 26px; margin-bottom: 4px; }
h2 { font-size: 19px; margin: 26px 0 12px; }
.sub { color: var(--dim); margin-bottom: 18px; }
.row { display: flex; gap: 12px; align-items: center; flex-wrap: wrap; }
.spacer { flex: 1; }

/* ---------- buttons / inputs ---------- */
.btn {
  display: inline-block; border: none; cursor: pointer;
  background: var(--accent); color: #062536;
  font-weight: 700; font-size: 14px;
  padding: 9px 18px; border-radius: 8px;
}
.btn:hover { filter: brightness(1.15); }
.btn.green { background: var(--accent2); color: #0a2a18; }
.btn.red { background: var(--red); color: #fff; }
.btn.gold { background: var(--gold); color: #4a3800; }
.btn.dark { background: var(--panel2); color: var(--text); border: 1px solid var(--line); }
.btn.big { font-size: 17px; padding: 13px 34px; }
.btn:disabled { opacity: .45; cursor: default; filter: none; }
input[type=text], input[type=password], input[type=number], textarea, select {
  background: var(--bg); border: 1px solid var(--line); color: var(--text);
  border-radius: 8px; padding: 9px 12px; font-size: 14px; font-family: inherit;
  outline: none; width: 100%;
}
input:focus, textarea:focus, select:focus { border-color: var(--accent); }
label.fld { display: block; margin-bottom: 12px; font-size: 13px; color: var(--dim); font-weight: 600; }
label.fld > * { margin-top: 4px; }

/* ---------- cards ---------- */
.panel { background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius); padding: 18px; }
.game-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(195px, 1fr)); gap: 14px; }
.game-card {
  background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius);
  overflow: hidden; cursor: pointer; transition: transform .12s, border-color .12s;
  display: block; color: var(--text);
}
.game-card:hover { transform: translateY(-3px); border-color: var(--accent); }
.game-card img { width: 100%; aspect-ratio: 16/9; display: block; background: #0e2233; }
.game-card .gc-body { padding: 10px 12px; }
.game-card .gc-name { font-weight: 700; font-size: 14px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.game-card .gc-meta { color: var(--dim); font-size: 12px; margin-top: 3px; display: flex; gap: 10px; }
.badge { font-size: 10px; font-weight: 800; padding: 2px 7px; border-radius: 20px; background: var(--accent); color: #062536; vertical-align: 2px; }
.badge.gray { background: var(--panel2); color: var(--dim); }

/* ---------- auth screen ---------- */
.auth-wrap { min-height: 100vh; display: flex; align-items: center; justify-content: center; flex-direction: column; gap: 26px;
  background: radial-gradient(1100px 500px at 50% -10%, #1d4257 0%, var(--bg) 60%); }
.auth-logo { text-align: center; }
.auth-logo .big-block { width: 74px; height: 74px; border-radius: 18px; margin: 0 auto 14px;
  background: linear-gradient(135deg, var(--accent), #1976d2); box-shadow: inset 0 0 0 13px rgba(14,28,38,.55), 0 12px 40px rgba(25,194,255,.25); }
.auth-logo h1 { font-size: 34px; letter-spacing: 2px; }
.auth-logo p { color: var(--dim); }
.auth-card { width: 340px; }
.auth-card .tabs { display: flex; margin-bottom: 16px; border-bottom: 1px solid var(--line); }
.auth-card .tabs button { flex: 1; background: none; border: none; color: var(--dim); font-weight: 700; font-size: 15px; padding: 10px; cursor: pointer; border-bottom: 2px solid transparent; }
.auth-card .tabs button.active { color: var(--accent); border-bottom-color: var(--accent); }
.err { color: var(--red); font-size: 13px; min-height: 18px; margin-bottom: 8px; }

/* ---------- hero ---------- */
.hero {
  border-radius: 16px; padding: 38px 34px; margin-bottom: 28px;
  background: linear-gradient(120deg, #14384d 0%, #0d5c74 55%, #0e7a5a 100%);
  border: 1px solid var(--line); position: relative; overflow: hidden;
}
.hero h1 { font-size: 32px; }
.hero p { color: #c5e8f5; margin: 8px 0 18px; max-width: 520px; }
.hero .blocks { position: absolute; right: -20px; top: -30px; font-size: 150px; opacity: .12; transform: rotate(12deg); }

/* ---------- game detail ---------- */
.game-head { display: flex; gap: 24px; flex-wrap: wrap; }
.game-head img.thumb { width: 420px; max-width: 100%; border-radius: var(--radius); border: 1px solid var(--line); }
.stat-row { display: flex; gap: 22px; margin: 14px 0; color: var(--dim); font-size: 14px; }
.stat-row b { color: var(--text); display: block; font-size: 17px; }
.desc { white-space: pre-wrap; color: var(--dim); line-height: 1.5; margin-top: 10px; }

/* ---------- catalog/avatar ---------- */
.item-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(150px, 1fr)); gap: 14px; }
.item-card { background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius); padding: 12px; text-align: center; }
.item-card.owned { border-color: var(--accent2); }
.item-card.equipped { border-color: var(--gold); box-shadow: 0 0 0 1px var(--gold); }
.item-thumb { width: 100%; aspect-ratio: 1; border-radius: 8px; background: var(--bg); margin-bottom: 8px; display:flex; align-items:center; justify-content:center; }
.item-thumb svg, .item-thumb canvas { max-width: 100%; max-height: 100%; }
.item-name { font-weight: 700; font-size: 13px; }
.item-price { color: var(--gold); font-size: 13px; margin: 4px 0 8px; }
.avatar-layout { display: flex; gap: 22px; flex-wrap: wrap; }
.avatar-preview { width: 340px; height: 420px; background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius); }
.avatar-preview canvas { width: 100%; height: 100%; border-radius: var(--radius); }
.color-swatches { display: flex; gap: 6px; flex-wrap: wrap; margin-top: 4px; }
.swatch { width: 26px; height: 26px; border-radius: 6px; cursor: pointer; border: 2px solid transparent; }
.swatch.sel { border-color: #fff; }

/* ---------- friends ---------- */
.friend-row { display: flex; align-items: center; gap: 12px; padding: 10px 0; border-bottom: 1px solid var(--line); }
.friend-row:last-child { border-bottom: none; }
.presence-dot { width: 9px; height: 9px; border-radius: 50%; background: #5a7482; display: inline-block; margin-right: 5px; }
.presence-dot.on { background: var(--accent2); }

/* ---------- toasts ---------- */
#toasts { position: fixed; bottom: 18px; right: 18px; z-index: 999; display: flex; flex-direction: column; gap: 8px; }
.toast {
  background: var(--panel2); border: 1px solid var(--accent); color: var(--text);
  border-radius: 10px; padding: 11px 18px; font-size: 14px; font-weight: 600;
  box-shadow: 0 8px 22px rgba(0,0,0,.45); animation: toast-in .2s ease;
}
.toast.gold { border-color: var(--gold); color: var(--gold); }
.toast.red { border-color: var(--red); }
@keyframes toast-in { from { transform: translateY(12px); opacity: 0; } }

/* ---------- play page (game client) ---------- */
#game-root { position: fixed; inset: 0; background: #000; z-index: 200; }
#game-root canvas.game-canvas { width: 100%; height: 100%; display: block; }
.hud { position: absolute; pointer-events: none; }
.hud * { pointer-events: auto; }
#hud-top { top: 10px; left: 12px; right: 12px; display: flex; align-items: flex-start; pointer-events: none; }
#hud-gamename { background: rgba(10,25,35,.75); border-radius: 8px; padding: 7px 14px; font-weight: 700; }
#hud-leave { margin-left: 10px; }
#hud-lb {
  margin-left: auto; background: rgba(10,25,35,.75); border-radius: 8px;
  min-width: 190px; padding: 8px 0; font-size: 13px;
}
#hud-lb .lb-title { padding: 0 12px 6px; color: var(--dim); font-weight: 700; border-bottom: 1px solid var(--line); display:flex; }
#hud-lb .lb-row { padding: 4px 12px; display: flex; }
#hud-lb .lb-row.it { color: #ff6b6b; font-weight: 700; }
#hud-lb .lb-row .v { margin-left: auto; }
#hud-chat { left: 12px; bottom: 12px; width: 330px; }
#chat-log { max-height: 180px; overflow-y: auto; font-size: 13px; margin-bottom: 6px; display: flex; flex-direction: column; gap: 2px; }
