// Tiny WebAudio synth — all sound effects generated, no audio files.
let ctx = null;

function ac() {
  if (!ctx) ctx = new (window.AudioContext || window.webkitAudioContext)();
  if (ctx.state === 'suspended') ctx.resume();
  return ctx;
}

function blip(freq, dur, type = 'square', vol = 0.08, slide = 0) {
  try {
    const a = ac();
    const osc = a.createOscillator();
    const gain = a.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, a.currentTime);
    if (slide) osc.frequency.exponentialRampToValueAtTime(Math.max(30, freq + slide), a.currentTime + dur);
    gain.gain.setValueAtTime(vol, a.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.001, a.currentTime + dur);
    osc.connect(gain).connect(a.destination);
    osc.start();
    osc.stop(a.currentTime + dur);
  } catch (e) { /* audio blocked until user gesture; fine */ }
}

export const sfx = {
  unlock() { try { ac(); } catch (e) {} },
  jump() { blip(220, 0.18, 'square', 0.05, 220); },
  coin() { blip(880, 0.09, 'square', 0.07); setTimeout(() => blip(1320, 0.14, 'square', 0.07), 70); },
  death() { blip(300, 0.4, 'sawtooth', 0.09, -240); },
  checkpoint() { blip(523, 0.1, 'triangle', 0.09); setTimeout(() => blip(784, 0.18, 'triangle', 0.09), 90); },
  goal() { [523, 659, 784, 1046].forEach((f, i) => setTimeout(() => blip(f, 0.22, 'triangle', 0.09), i * 110)); },
  tag() { blip(700, 0.12, 'sawtooth', 0.08, -300); },
  tele() { blip(400, 0.25, 'sine', 0.09, 800); },
  bounce() { blip(180, 0.2, 'sine', 0.1, 320); },
  chat() { blip(1200, 0.05, 'sine', 0.03); },
};

