// SPA router + all site pages.
import * as THREE from 'three';
import { api, state, refreshMe, loadCatalog, catalogItem, toast, esc, fmtNum, openWS } from './api.js';
import { avatarSVG, faceDataURL } from './avatar2d.js';
import { GameClient } from './engine/game.js';
import { Studio } from './studio/studio.js';
import { Character } from './engine/player.js';

const page = document.getElementById('page');
const nav = document.getElementById('topnav');
let activeApp = null; // running GameClient or Studio

// ---------------- router ----------------
const routes = [
  [/^#?\/?$/, renderHome],
  [/^#\/discover/, renderDiscover],
  [/^#\/game\/([\w-]+)/, renderGamePage],
  [/^#\/play\/([\w-]+)/, renderPlay],
  [/^#\/studio\/([\w-]+)/, renderStudio],
  [/^#\/studio/, renderStudioList],
  [/^#\/avatar/, renderAvatar],
  [/^#\/catalog/, renderCatalog],
  [/^#\/friends/, renderFriends],
  [/^#\/profile\/([\w-]+)/, renderProfile],
];

async function route() {
  if (activeApp) { const a = activeApp; activeApp = null; a.exit && a.alive && a.exit(); }
  page.className = '';
  document.body.style.overflow = '';

  if (!state.me) {
    renderAuth();
    return;
  }
  nav.classList.remove('hidden');
  updateNavUser();

  const hash = location.hash || '#/';
  for (const [re, fn] of routes) {
    const m = hash.match(re);
    if (m) {
      document.querySelectorAll('#topnav [data-nav]').forEach((a) => {
        a.classList.toggle('active', hash.startsWith(a.getAttribute('href')) && a.getAttribute('href') !== '#/' || (a.getAttribute('href') === '#/' && (hash === '#/' || hash === '')));
      });
      try {
        await fn(...m.slice(1));
      } catch (e) {
        page.innerHTML = `<div class="empty-note">⚠️ ${esc(e.message)}</div>`;
      }
      return;
    }
  }
  page.innerHTML = '<div class="empty-note">Page not found</div>';
}

addEventListener('hashchange', route);

function updateNavUser() {
  document.getElementById('nav-username').textContent = state.me.username;
  document.getElementById('nav-glimmers').textContent = '◈ ' + fmtNum(state.me.glimmers);
  document.getElementById('nav-avatar').innerHTML = avatarSVG(state.me.avatar, 30);
  document.getElementById('nav-profile').href = '#/profile/' + state.me.username;
}

document.getElementById('nav-logout').onclick = async () => {
  await api('/logout', { method: 'POST', body: {} });
  state.me = null;
  location.hash = '#/';
  route();
};

// ---------------- auth ----------------
function renderAuth() {
  nav.classList.add('hidden');
  page.className = 'full';
  page.innerHTML = `
    <div class="auth-wrap">
      <div class="auth-logo">
        <div class="big-block"></div>
        <h1>GLINT</h1>
        <p>Research's Legally Distinct Clone</p>
        <p style="font-size:13px;margin-top:6px">Play together. Build together. Definitely not that other site.</p>
      </div>
      <div class="panel auth-card">
        <div class="tabs">
          <button id="tab-login" class="active">Log in</button>
          <button id="tab-register">Sign up</button>
        </div>
        <div class="err" id="auth-err"></div>
        <label class="fld">Username<input type="text" id="auth-user" maxlength="20" autocomplete="username"></label>
        <label class="fld">Password<input type="password" id="auth-pass" autocomplete="current-password"></label>
        <button class="btn big" style="width:100%" id="auth-go">Log in</button>
        <p style="color:var(--dim);font-size:12px;margin-top:12px" id="auth-hint">New here? Sign up — you get 250 ◈ Glimmers free.</p>
      </div>
    </div>
  `;
  let mode = 'login';
  const setMode = (m) => {
    mode = m;
    document.getElementById('tab-login').classList.toggle('active', m === 'login');
    document.getElementById('tab-register').classList.toggle('active', m === 'register');
    document.getElementById('auth-go').textContent = m === 'login' ? 'Log in' : 'Create account';
  };
  document.getElementById('tab-login').onclick = () => setMode('login');
  document.getElementById('tab-register').onclick = () => setMode('register');
  const go = async () => {
    const errEl = document.getElementById('auth-err');
    errEl.textContent = '';
    try {
      const data = await api('/' + mode, {
        body: {
          username: document.getElementById('auth-user').value.trim(),
          password: document.getElementById('auth-pass').value,
        },
      });
      state.me = data.user;
      if (mode === 'register') toast('Welcome! +250 ◈ signup bonus', 'gold');
      location.hash = '#/';
      route();
    } catch (e) {
      errEl.textContent = e.message;
    }
  };
  document.getElementById('auth-go').onclick = go;
  page.querySelectorAll('input').forEach((i) => i.addEventListener('keydown', (e) => { if (e.key === 'Enter') go(); }));
}

// ---------------- shared UI bits ----------------
function gameCard(g) {
  return `<a class="game-card" href="#/game/${g.id}">
    <img src="/api/games/${g.id}/thumb.svg?v=${g.updated}" alt="">
    <div class="gc-body">
      <div class="gc-name">${esc(g.name)} ${g.official ? '<span class="badge">OFFICIAL</span>' : ''}${!g.public ? '<span class="badge gray">PRIVATE</span>' : ''}</div>
      <div class="gc-meta"><span>👤 ${fmtNum(g.visits)}</span><span>👍 ${fmtNum(g.likeCount)}</span><span>${esc(g.genre)}</span></div>
    </div>
  </a>`;
}

function gameGrid(games) {
  if (!games.length) return '<div class="empty-note">Nothing here yet</div>';
  return `<div class="game-grid">${games.map(gameCard).join('')}</div>`;
}

// ---------------- pages ----------------
async function renderHome() {
  const { games } = await api('/games?sort=popular');
  const official = games.filter((g) => g.official);
  const community = games.filter((g) => !g.official);
  page.innerHTML = `
    <div class="hero">
      <div class="blocks">🟦🟩🟨</div>
      <h1>Hey, ${esc(state.me.username)}!</h1>
      <p>Jump into an official game, discover community creations, or open Studio and build your own world with friends — live, together.</p>
      <a class="btn big green" href="#/studio">🔧 Start Building</a>
      <a class="btn big" href="#/discover" style="margin-left:8px">🎮 Discover Games</a>
    </div>
    <h2>⭐ Official Games</h2>
    ${gameGrid(official)}
    <h2>🌍 Community Picks</h2>
    ${community.length ? gameGrid(community) : '<div class="empty-note">No community games yet — be the first! Open <a href="#/studio">Studio</a>.</div>'}
  `;
}

async function renderDiscover() {
  page.innerHTML = `
    <h1>Discover</h1>
    <p class="sub">Every public game on the platform</p>
    <div class="row" style="margin-bottom:16px">
      <input type="text" id="disc-q" placeholder="Search games…" style="max-width:300px">
      <select id="disc-sort" style="max-width:160px">
        <option value="popular">Most visited</option>
        <option value="liked">Most liked</option>
        <option value="new">Newest</option>
      </select>
    </div>
    <div id="disc-results"></div>
  `;
  const load = async () => {
    const q = encodeURIComponent(document.getElementById('disc-q').value.trim());
    const sort = document.getElementById('disc-sort').value;
    const { games } = await api(`/games?q=${q}&sort=${sort}`);
    document.getElementById('disc-results').innerHTML = gameGrid(games);
  };
  let t;
  document.getElementById('disc-q').addEventListener('input', () => { clearTimeout(t); t = setTimeout(load, 250); });
  document.getElementById('disc-sort').addEventListener('change', load);
  await load();
}

async function renderGamePage(id) {
  const { game: g } = await api('/games/' + id);
  const cfg = g.config;
  page.innerHTML = `
    <div class="game-head">
      <img class="thumb" src="/api/games/${g.id}/thumb.svg?v=${g.updated}" alt="">
      <div style="flex:1;min-width:280px">
        <h1>${esc(g.name)} ${g.official ? '<span class="badge">OFFICIAL</span>' : ''}${!g.public ? '<span class="badge gray">PRIVATE</span>' : ''}</h1>
        <p class="sub">by <a href="#/profile/${esc(g.owner.username)}">${esc(g.owner.username)}</a>
          ${g.collaborators.length ? ' · with ' + g.collaborators.map((c) => `<a href="#/profile/${esc(c.username)}">${esc(c.username)}</a>`).join(', ') : ''}</p>
        <div class="stat-row">
          <span><b>${fmtNum(g.visits)}</b>Visits</span>
          <span><b>${fmtNum(g.likeCount)}</b>Likes</span>
          <span><b>${fmtNum(g.favCount)}</b>Favorites</span>
          <span><b>${esc(g.genre)}</b>Genre</span>
        </div>
        <div class="row">
          <a class="btn big green" href="#/play/${g.id}">▶ Play</a>
          <button class="btn dark" id="g-like">${g.liked ? '👍 Liked' : '👍 Like'}</button>
          <button class="btn dark" id="g-fav">${g.favorited ? '⭐ Favorited' : '⭐ Favorite'}</button>
          ${g.canEdit ? `<a class="btn gold" href="#/studio/${g.id}">🔧 Edit in Studio</a>` : ''}
        </div>
        <div class="desc">${esc(g.desc) || '<i>No description</i>'}</div>
      </div>
    </div>
    <h2>Server Config</h2>
    <div class="panel" style="max-width:460px">
      <table class="cfg">
        <tr><td>Game mode</td><td>${esc(cfg.mode)}</td></tr>
        <tr><td>Max players / server</td><td>${cfg.maxPlayers}</td></tr>
        <tr><td>Gravity</td><td>${cfg.gravity}</td></tr>
        <tr><td>Walk speed</td><td>${cfg.walkSpeed}</td></tr>
        <tr><td>Jump power</td><td>${cfg.jumpPower}</td></tr>
        <tr><td>Parts in world</td><td>${g.partCount}</td></tr>
      </table>
    </div>
    ${g.canEdit && state.me.id === g.owner.id ? `
    <h2>Collaborators</h2>
    <div class="panel" style="max-width:460px">
      <p class="sub" style="margin-bottom:10px">Collaborators can edit this place with you in Studio — live.</p>
      <div id="collab-list">${g.collaborators.map((c) => `<div class="friend-row"><span>${esc(c.username)}</span><span class="spacer"></span><button class="ghost-btn" data-rm="${esc(c.username)}">Remove</button></div>`).join('') || '<div style="color:var(--dim)">None yet</div>'}</div>
      <div class="row" style="margin-top:10px">
        <input type="text" id="collab-name" placeholder="Username" style="max-width:200px">
        <button class="btn" id="collab-add">Add</button>
      </div>
      <div class="row" style="margin-top:14px">
        <button class="btn red" id="g-delete">Delete game</button>
      </div>
    </div>` : ''}
  `;
  document.getElementById('g-like').onclick = async () => {
    const r = await api(`/games/${g.id}/like`, { method: 'POST', body: {} });
    document.getElementById('g-like').textContent = r.liked ? '👍 Liked' : '👍 Like';
  };
  document.getElementById('g-fav').onclick = async () => {
    const r = await api(`/games/${g.id}/favorite`, { method: 'POST', body: {} });
    document.getElementById('g-fav').textContent = r.favorited ? '⭐ Favorited' : '⭐ Favorite';
  };
  const addBtn = document.getElementById('collab-add');
  if (addBtn) {
    addBtn.onclick = async () => {
      try {
        await api(`/games/${g.id}/collaborators`, { body: { username: document.getElementById('collab-name').value.trim(), action: 'add' } });
        toast('Collaborator added');
        renderGamePage(id);
      } catch (e) { toast(e.message, 'red'); }
    };
    page.querySelectorAll('[data-rm]').forEach((b) => {
      b.onclick = async () => {
        await api(`/games/${g.id}/collaborators`, { body: { username: b.dataset.rm, action: 'remove' } });
        renderGamePage(id);
      };
    });
    document.getElementById('g-delete').onclick = async () => {
      if (!confirm(`Delete "${g.name}" forever?`)) return;
      await api('/games/' + g.id, { method: 'DELETE' });
      toast('Game deleted');
      location.hash = '#/studio';
    };
  }
}

async function renderPlay(id) {
  page.className = 'full';
  nav.classList.add('hidden');
  document.body.style.overflow = 'hidden';
  await loadCatalog();
  page.innerHTML = '<div id="game-root"></div>';
  activeApp = new GameClient(document.getElementById('game-root'), id, () => {
    nav.classList.remove('hidden');
    activeApp = null;
    refreshMe().then(updateNavUser);
    location.hash = '#/game/' + id;
  });
}

async function renderStudioList() {
  const { games } = await api('/games?mine=1');
  page.innerHTML = `
    <h1>Create</h1>
    <p class="sub">Your places. Open one in Studio, invite collaborators, build live together.</p>
    <div class="row" style="margin-bottom:18px">
      <input type="text" id="new-name" placeholder="New place name…" style="max-width:280px" maxlength="50">
      <button class="btn green" id="new-go">+ Create Place</button>
    </div>
    ${games.length ? `<div class="game-grid">${games.map((g) => `
      <div class="game-card">
        <a href="#/game/${g.id}"><img src="/api/games/${g.id}/thumb.svg?v=${g.updated}" alt=""></a>
        <div class="gc-body">
          <div class="gc-name">${esc(g.name)} ${!g.public ? '<span class="badge gray">PRIVATE</span>' : ''}</div>
          <div class="gc-meta"><span>👤 ${fmtNum(g.visits)}</span><span>${g.owner.id === state.me.id ? 'Owner' : 'Collaborator'}</span></div>
          <div class="row" style="margin-top:8px">
            <a class="btn gold" style="flex:1;text-align:center" href="#/studio/${g.id}">🔧 Edit</a>
            <a class="btn green" style="flex:1;text-align:center" href="#/play/${g.id}">▶ Play</a>
          </div>
        </div>
      </div>`).join('')}</div>`
      : '<div class="empty-note">No places yet. Create your first one above! 🚀</div>'}
  `;
  document.getElementById('new-go').onclick = async () => {
    const name = document.getElementById('new-name').value.trim() || 'Untitled Place';
    const { game } = await api('/games', { body: { name } });
    location.hash = '#/studio/' + game.id;
  };
}

async function renderStudio(id) {
  page.className = 'full';
  nav.classList.add('hidden');
  document.body.style.overflow = 'hidden';
  page.innerHTML = '<div id="studio-root"></div>';
  activeApp = new Studio(document.getElementById('studio-root'), id, (to) => {
    nav.classList.remove('hidden');
    activeApp = null;
    location.hash = to || '#/studio';
  });
}

// ---------------- avatar editor ----------------
let avatarPreview = null;

function startAvatarPreview(canvas) {
  const renderer = new THREE.WebGLRenderer({ canvas, antialias: true });
  renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
  const scene = new THREE.Scene();
  scene.background = new THREE.Color(0x142733);
  scene.add(new THREE.AmbientLight(0xffffff, 1.2));
  const key = new THREE.DirectionalLight(0xffffff, 1.8);
  key.position.set(3, 5, 4);
  scene.add(key);
  const camera = new THREE.PerspectiveCamera(45, 1, 0.1, 50);
  camera.position.set(0, 0.4, 6.5);
  camera.lookAt(0, 0, 0);
  const stand = new THREE.Mesh(
    new THREE.CylinderGeometry(1.6, 1.8, 0.3, 32),
    new THREE.MeshStandardMaterial({ color: 0x224050 })
  );
  stand.position.y = -2.6;
  scene.add(stand);

  const ctx = { renderer, scene, camera, char: null, alive: true };
  const animate = () => {
    if (!ctx.alive) return;
    requestAnimationFrame(animate);
    const w = canvas.clientWidth, h = canvas.clientHeight;
    if (canvas.width !== w * renderer.getPixelRatio()) {
      renderer.setSize(w, h, false);
      camera.aspect = w / Math.max(1, h);
      camera.updateProjectionMatrix();
    }
    if (ctx.char) {
      ctx.char.group.rotation.y += 0.008;
      ctx.char.animate(0.016, 'idle');
    }
    renderer.render(scene, camera);
  };
  animate();
  return ctx;
}

function setPreviewAvatar(av) {
  if (!avatarPreview) return;
  if (avatarPreview.char) avatarPreview.char.dispose();
  avatarPreview.char = new Character(av, null, state.catalog);
  avatarPreview.char.group.position.y = -0.3;
  avatarPreview.scene.add(avatarPreview.char.group);
}

async function renderAvatar() {
  await loadCatalog();
  if (avatarPreview) { avatarPreview.alive = false; avatarPreview = null; }
  const draft = JSON.parse(JSON.stringify(state.me.avatar));
  const BODY_PARTS = [['head', 'Head'], ['torso', 'Torso'], ['leftArm', 'L Arm'], ['rightArm', 'R Arm'], ['leftLeg', 'L Leg'], ['rightLeg', 'R Leg']];
  const COLORS = ['#ffd23f', '#ffb74d', '#e8a87c', '#bf8a65', '#8d5e3c', '#e54b4b', '#f0a020', '#3aa14f', '#19ff8c', '#2a7de1', '#19c2ff', '#8a4fff', '#ff5e9c', '#cfd8dc', '#78909c', '#37474f', '#ffffff', '#1b1b1b'];

  const ownedHats = state.catalog.filter((i) => i.type === 'hat' && state.me.inventory.includes(i.id));
  const ownedFaces = state.catalog.filter((i) => i.type === 'face' && state.me.inventory.includes(i.id));

  page.innerHTML = `
    <h1>Avatar</h1>
    <p class="sub">Dress your blocky self. Changes show up in every game.</p>
    <div class="avatar-layout">
      <div class="avatar-preview"><canvas></canvas></div>
      <div style="flex:1;min-width:300px">
        <h2 style="margin-top:0">Body Colors</h2>
        <div id="av-body"></div>
        <h2>Face</h2>
        <div class="item-grid" id="av-faces"></div>
        <h2>Hats <a href="#/catalog" style="font-size:13px;font-weight:400">— get more in the Catalog</a></h2>
        <div class="item-grid" id="av-hats"></div>
        <button class="btn big green" id="av-save" style="margin-top:18px">Save Avatar</button>
      </div>
    </div>
  `;

  avatarPreview = startAvatarPreview(page.querySelector('.avatar-preview canvas'));
  setPreviewAvatar(draft);

  const bodyEl = document.getElementById('av-body');
  let selPart = 'torso';
  const renderBody = () => {
    bodyEl.innerHTML = `
      <div class="row" style="margin-bottom:8px">${BODY_PARTS.map(([k, label]) =>
        `<button class="tool-btn${selPart === k ? ' active' : ''}" data-part="${k}">${label}</button>`).join('')}</div>
      <div class="color-swatches">${COLORS.map((c) =>
        `<span class="swatch${draft.bodyColors[selPart] === c ? ' sel' : ''}" data-c="${c}" style="background:${c}"></span>`).join('')}</div>
    `;
    bodyEl.querySelectorAll('[data-part]').forEach((b) => b.onclick = () => { selPart = b.dataset.part; renderBody(); });
    bodyEl.querySelectorAll('[data-c]').forEach((s) => s.onclick = () => {
      draft.bodyColors[selPart] = s.dataset.c;
      renderBody();
      setPreviewAvatar(draft);
    });
  };
  renderBody();

  const facesEl = document.getElementById('av-faces');
  const hatsEl = document.getElementById('av-hats');
  const renderItems = () => {
    facesEl.innerHTML = ownedFaces.map((i) => `
      <div class="item-card${draft.face === i.id ? ' equipped' : ' owned'}" data-id="${i.id}">
        <div class="item-thumb"><img src="${faceDataURL(i.face, 80, '#ffd23f')}" width="64"></div>
        <div class="item-name">${esc(i.name)}</div>
        <button class="btn dark" style="margin-top:6px">${draft.face === i.id ? 'Equipped' : 'Equip'}</button>
      </div>`).join('');
    hatsEl.innerHTML = `
      <div class="item-card${!draft.hat ? ' equipped' : ' owned'}" data-id="">
        <div class="item-thumb" style="font-size:34px">🚫</div>
        <div class="item-name">No Hat</div>
        <button class="btn dark" style="margin-top:6px">${!draft.hat ? 'Equipped' : 'Equip'}</button>
      </div>` + ownedHats.map((i) => `
      <div class="item-card${draft.hat === i.id ? ' equipped' : ' owned'}" data-id="${i.id}">
        <div class="item-thumb"><span style="font-size:30px;color:${i.mesh.color}">⬢</span></div>
        <div class="item-name">${esc(i.name)}</div>
        <button class="btn dark" style="margin-top:6px">${draft.hat === i.id ? 'Equipped' : 'Equip'}</button>
      </div>`).join('');
    facesEl.querySelectorAll('.item-card').forEach((c) => c.onclick = () => {
      draft.face = c.dataset.id; renderItems(); setPreviewAvatar(draft);
    });
    hatsEl.querySelectorAll('.item-card').forEach((c) => c.onclick = () => {
      draft.hat = c.dataset.id || null; renderItems(); setPreviewAvatar(draft);
    });
  };
  renderItems();

  document.getElementById('av-save').onclick = async () => {
    const r = await api('/avatar', { body: draft });
    state.me.avatar = r.avatar;
    updateNavUser();
    toast('Avatar saved ✓');
  };
}

async function renderCatalog() {
  await loadCatalog();
  const renderList = () => {
    page.innerHTML = `
      <h1>Catalog</h1>
      <p class="sub">Spend your ◈ Glimmers. Earn more daily, and +1 every time someone visits your games.</p>
      <h2>Hats</h2>
      <div class="item-grid">${state.catalog.filter((i) => i.type === 'hat').map(itemCard).join('')}</div>
      <h2>Faces</h2>
      <div class="item-grid">${state.catalog.filter((i) => i.type === 'face').map(itemCard).join('')}</div>
    `;
    page.querySelectorAll('[data-buy]').forEach((b) => {
      b.onclick = async () => {
        try {
          const r = await api(`/catalog/${b.dataset.buy}/buy`, { method: 'POST', body: {} });
          state.me.glimmers = r.glimmers;
          state.me.inventory = r.inventory;
          updateNavUser();
          toast('Purchased! Equip it on the Avatar page.', 'gold');
          renderList();
        } catch (e) { toast(e.message, 'red'); }
      };
    });
  };
  function itemCard(i) {
    const owned = state.me.inventory.includes(i.id);
    const thumb = i.type === 'face'
      ? `<img src="${faceDataURL(i.face, 80, '#ffd23f')}" width="64">`
      : `<span style="font-size:34px;color:${i.mesh.color}">⬢</span>`;
    return `<div class="item-card${owned ? ' owned' : ''}">
      <div class="item-thumb">${thumb}</div>
      <div class="item-name">${esc(i.name)}</div>
      <div class="item-price">${i.price === 0 ? 'Free' : '◈ ' + i.price}</div>
      ${owned ? '<span class="badge">OWNED</span>' : `<button class="btn gold" data-buy="${i.id}">Buy</button>`}
    </div>`;
  }
  renderList();
}

async function renderFriends() {
  const { friends, requests } = await api('/friends');
  page.innerHTML = `
    <h1>Friends</h1>
    <p class="sub">See who's online and jump into their game.</p>
    <div class="row" style="margin-bottom:18px">
      <input type="text" id="fr-name" placeholder="Add friend by username…" style="max-width:260px">
      <button class="btn" id="fr-add">Send request</button>
    </div>
    ${requests.length ? `<h2>Requests</h2><div class="panel">${requests.map((r) => `
      <div class="friend-row">
        <span class="mini-avatar">${avatarSVG(r.avatar, 30)}</span>
        <a href="#/profile/${esc(r.username)}">${esc(r.username)}</a>
        <span class="spacer"></span>
        <button class="btn green" data-acc="${r.id}">Accept</button>
        <button class="btn dark" data-dec="${r.id}">Decline</button>
      </div>`).join('')}</div>` : ''}
    <h2>Friends (${friends.length})</h2>
    <div class="panel">${friends.length ? friends.map((f) => `
      <div class="friend-row">
        <span class="mini-avatar">${avatarSVG(f.avatar, 30)}</span>
        <a href="#/profile/${esc(f.username)}">${esc(f.username)}</a>
        <span style="color:var(--dim);font-size:13px"><span class="presence-dot${f.online ? ' on' : ''}"></span>${f.playing ? 'Playing ' + esc(f.playing.gameName || '') : f.online ? 'Online' : 'Offline'}</span>
        <span class="spacer"></span>
        ${f.playing ? `<a class="btn green" href="#/play/${f.playing.gameId}">Join</a>` : ''}
        <button class="ghost-btn" data-unf="${f.id}">Unfriend</button>
      </div>`).join('') : '<div class="empty-note">No friends yet. Add someone by username above!</div>'}</div>
  `;
  document.getElementById('fr-add').onclick = async () => {
    try {
      const r = await api('/friends/request', { body: { username: document.getElementById('fr-name').value.trim() } });
      toast(r.becameFriends ? 'You are now friends!' : 'Request sent');
      renderFriends();
    } catch (e) { toast(e.message, 'red'); }
  };
  page.querySelectorAll('[data-acc]').forEach((b) => b.onclick = async () => {
    await api('/friends/respond', { body: { userId: b.dataset.acc, accept: true } });
    renderFriends();
  });
  page.querySelectorAll('[data-dec]').forEach((b) => b.onclick = async () => {
    await api('/friends/respond', { body: { userId: b.dataset.dec, accept: false } });
    renderFriends();
  });
  page.querySelectorAll('[data-unf]').forEach((b) => b.onclick = async () => {
    await api('/friends/' + b.dataset.unf, { method: 'DELETE' });
    renderFriends();
  });
}

async function renderProfile(username) {
  if (username === 'me') username = state.me.username;
  const { user, friendCount, games } = await api('/users/' + encodeURIComponent(username));
  const isMe = user.id === state.me.id;
  page.innerHTML = `
    <div class="row" style="gap:20px;align-items:flex-start">
      <div class="panel" style="width:170px;text-align:center">
        <div style="width:120px;margin:0 auto">${avatarSVG(user.avatar, 120)}</div>
      </div>
      <div>
        <h1>${esc(user.username)} ${user.system ? '<span class="badge">PLATFORM</span>' : ''}</h1>
        <p class="sub">Joined ${new Date(user.created).toLocaleDateString()}</p>
        <div class="stat-row">
          <span><b>${fmtNum(user.stats.visitsReceived)}</b>Game visits</span>
          <span><b>${fmtNum(user.stats.joins)}</b>Games played</span>
          <span><b>${friendCount}</b>Friends</span>
        </div>
        ${!isMe && !user.system ? `<button class="btn" id="pf-add">Add friend</button>` : ''}
        ${isMe ? `<a class="btn dark" href="#/avatar">Edit avatar</a>` : ''}
      </div>
    </div>
    <h2>Creations</h2>
    ${gameGrid(games)}
  `;
  const addBtn = document.getElementById('pf-add');
  if (addBtn) addBtn.onclick = async () => {
    try {
      const r = await api('/friends/request', { body: { username: user.username } });
      toast(r.becameFriends ? 'You are now friends!' : 'Request sent');
    } catch (e) { toast(e.message, 'red'); }
  };
}

// ---------------- boot ----------------
(async () => {
  try { await refreshMe(); } catch (e) { /* not logged in */ }
  if (state.me) await loadCatalog().catch(() => {});
  route();
})();

