// Integration test: two real users exercise REST + WebSocket flows.
const WebSocket = require('/home/lane/rblx/node_modules/ws');
const BASE = 'http://localhost:3001';

let pass = 0, fail = 0;
function ok(name, cond) {
  if (cond) { pass++; console.log('  ✓', name); }
  else { fail++; console.log('  ✗ FAIL', name); }
}

async function call(path, opts = {}, cookie = '') {
  const res = await fetch(BASE + '/api' + path, {
    method: opts.method || (opts.body ? 'POST' : 'GET'),
    headers: Object.assign({ 'Content-Type': 'application/json', Cookie: cookie }),
    body: opts.body ? JSON.stringify(opts.body) : undefined,
  });
  const setCookie = res.headers.get('set-cookie') || '';
  const data = await res.json().catch(() => ({}));
  return { status: res.status, data, cookie: setCookie.split(';')[0] };
}

function wsConnect(cookie) {
  return new Promise((resolve, reject) => {
    const ws = new WebSocket('ws://localhost:3001/ws', { headers: { Cookie: cookie } });
    ws.inbox = [];
    ws.waiters = [];
    ws.on('message', (raw) => {
      const msg = JSON.parse(raw);
      const w = ws.waiters.find((x) => x.t === msg.t);
      if (w) { ws.waiters.splice(ws.waiters.indexOf(w), 1); w.resolve(msg); }
      else ws.inbox.push(msg);
    });
    ws.on('open', () => resolve(ws));
    ws.on('error', reject);
  });
}

function expect(ws, t, timeout = 4000) {
  const found = ws.inbox.find((m) => m.t === t);
  if (found) { ws.inbox.splice(ws.inbox.indexOf(found), 1); return Promise.resolve(found); }
  return new Promise((resolve, reject) => {
    const w = { t, resolve };
    ws.waiters.push(w);
    setTimeout(() => reject(new Error('timeout waiting for ' + t)), timeout);
  });
}

